<template><ToolShell :eyebrow="label('Resource search', 'Búsqueda de recursos')" :title="label('Find the right Klyrow page', 'Encuentra la página adecuada')" :description="label('Search the static public content index without sending the query to a third-party search service.', 'Busca en el índice público estático sin enviar la consulta a un buscador externo.')"><form class="stack" @submit.prevent="run"><BaseInput id="content-search" v-model="query" name="query" :label="label('Search', 'Buscar')" required /><BaseButton type="submit" :disabled="pending">{{ label('Search content', 'Buscar contenido') }}</BaseButton><BaseAlert v-if="errorMessage" tone="danger">{{ errorMessage }}</BaseAlert><div class="stack"><BaseCard v-for="entry in results" :key="entry.id"><NuxtLink :to="entry.path"><h3>{{ entry.title }}</h3><p>{{ entry.summary }}</p></NuxtLink></BaseCard></div></form></ToolShell></template>
<script setup lang="ts">interface Result{id:string;path:string;title:string;summary:string}const{locale}=useLocale();const label=(en:string,es:string)=>locale.value==='es'?es:en;const query=ref('');const results=ref<Result[]>([]);const pending=ref(false);const errorMessage=ref('');const run=async()=>{pending.value=true;errorMessage.value='';try{const response=await $fetch<{data:Result[]}>(`/api/v1/tools/content-search?q=${encodeURIComponent(query.value)}&locale=${locale.value}`);results.value=response.data}catch{errorMessage.value=label('Search is temporarily unavailable.','La búsqueda no está disponible temporalmente.')}finally{pending.value=false}}</script>
